# AI-Lab (2026-10-12): preload this env's pip CUDA libs (cuBLAS, NVRTC, cuDNN) so ctranslate2 finds
# them by soname. This replaces /etc/ld.so.conf.d/faster-whisper-cuda.conf, which put cuDNN 9.24 in
# the GLOBAL loader cache: every other env on ai-epyc (chatterbox TTS = cuDNN 9.20) then picked up
# the missing libcudnn_engines_tensor_ir.so.9 from here -> CUDNN_STATUS_SUBLIBRARY_VERSION_MISMATCH,
# and all TTS returned 500. Scoped to this env only; never put a per-env lib dir in ld.so.conf.d.
import ctypes, glob, os, sys
_sp = os.path.join(os.path.dirname(__file__), "nvidia")
for _pat in ("cublas/lib/libcublasLt.so.*", "cublas/lib/libcublas.so.*", "cuda_nvrtc/lib/libnvrtc.so.*",
             "cudnn/lib/libcudnn_graph.so.*", "cudnn/lib/libcudnn_*.so.*", "cudnn/lib/libcudnn.so.*"):
    for _f in sorted(glob.glob(os.path.join(_sp, _pat))):
        try:
            ctypes.CDLL(_f, mode=ctypes.RTLD_GLOBAL)
        except OSError as _e:
            print(f"[sitecustomize] preload {_f} failed: {_e}", file=sys.stderr)
